les(0,"The same bug by a second route",[
 ["setup","Sarvam does not wait for a full sentence","It marks pieces of text finished as it goes."],
 ["before","A finished piece ended the turn","Even mid-sentence, if the gap was shorter than <code>stop_secs</code>, so no stop frame was ever sent."],
 ["now","A partial piece arriving after cancels that","The turn stays open for the rest of the sentence."],
 ["us","This one reaches us","The fix is triggered by a partial piece of text arriving. Our speech-to-text service does send those, so the guard can fire."]
]);

les(0,"Replying to a fragment",[
 ["setup","One spoken answer often arrives in pieces","Speech-to-text splits it up."],
 ["before","Each piece counted as a whole turn","The agent replied to the first fragment while the caller kept going."],
 ["now","It waits for the whole sentence",""],
 ["us","Most common on quick openings","Which is exactly how people start an answer."]
]);

les(0,"The pause detector freezing after a mute",[
 ["setup","Bulk dictation judges the end with a model","And we mute the caller at times, such as while the agent is speaking."],
 ["before","A mute could freeze that model mid-speech","Later, while the agent was already replying, it would announce that the caller had stopped, which was no longer true."],
 ["now","It is cleared on every path that ends a turn","No stale decision can surface afterwards."],
 ["us","This exact combination is live in production","The pause model plus muting, in bulk dictation."]
]);

les(0,"Cutting in on a stale signal",[
 ["setup","Signals about who is speaking can arrive late",""],
 ["before","A late stop signal still ended the turn","Even though the caller had started speaking again. The agent talked over them."],
 ["now","An out-of-date signal is ignored",""],
 ["us","This closes the last of four","Together with the three lessons before it, every route to being talked over is now shut."]
]);

les(0,"Answering twice",[
 ["before","The agent could answer the same turn twice","Or run its thinking step twice for one turn."],
 ["now","One answer per turn",""],
 ["us","Two thinking runs means two model calls","So this cost money as well as sounding wrong."]
]);

les(0,"The wait counted thinking time twice",[
 ["setup","There is a safety timer for a slow decision",""],
 ["before","Deciding time was added on top of the timer","And once the model did decide early, the code waited out the full timer anyway."],
 ["now","Deciding time counts against the timer","An early decision ends the turn straight away."],
 ["now","The turn now ends when the decision is made","Not when a timer that was already running happens to expire. Bulk dictation reacts sooner once someone stops."]
]);

les(0,"A nudge at someone who is talking",[
 ["setup","There is a gentle prompt for a caller gone quiet",""],
 ["before","It could fire at a caller who had resumed","They were talking, and got nudged."],
 ["now","It does not",""],
 ["us","Small, but people remember it","Being interrupted mid-answer is what a health worker takes away from a call."]
]);

les(0,"A dip between two words",[
 ["setup","Loudness is how it decides a voice is present","Every other decision in this module sits on top of that one signal."],
 ["before","It was read at a single instant","A dip between two syllables registered as silence."],
 ["now","Measured over just under half a second","Which rides straight over those dips."],
 ["us","Fewer false quiet moments","And everything else here depends on that signal being right."]
]);

les(1,"Silent forever on an empty reply",[
 ["setup","A voice provider can succeed and return no audio","An exhausted quota does exactly this."],
 ["before","The call froze permanently","The caller heard nothing, and nothing recovered it."],
 ["now","A three second timer un-sticks it","And reports a real error instead of hanging."],
 ["us","Google is our production voice, and it gets this","A second guard stops using a voice after three silent replies in a row."]
]);

les(1,"A caller muted for the whole call",[
 ["setup","We mute the caller until the greeting finishes","So the opening line is not talked over."],
 ["before","Unmuting only happened when speech finished","If that first reply produced no audio, the unmute never came."],
 ["now","An error before the first words also lifts the mute",""],
 ["us","We use exactly this mute rule","So this was a live risk, not a theoretical one."]
]);

les(1,"A turn with no speech froze the conversation",[
 ["before","The whole call briefly froze","Until a safety timer forced it onward. Seconds of dead air mid-conversation."],
 ["now","It moves on immediately",""],
 ["us","The error is the same either way","What changed is that it no longer blocks teardown, so the call completes instead of hanging."]
]);

les(1,"A stuck audio send",[
 ["before","Sending audio could block with no limit","The agent went silent for the rest of the call."],
 ["now","Capped at ten seconds",""],
 ["us","One of several waits given a limit","Before this release, several places would wait indefinitely. This one is now capped."]
]);

les(1,"A hanging setup step",[
 ["setup","Starting a call means connecting several services","Speech-to-text, text-to-speech, and noise removal."],
 ["before","If one hung, the call hung with it, indefinitely",""],
 ["now","Torn down after twenty seconds",""],
 ["us","We already wrote a guard of our own","If the noise filter cannot load its model, our code lets the call run without noise removal rather than die."]
]);

les(1,"One failed cleanup blocked the rest",[
 ["before","If one piece failed to clean up, none of the others could",""],
 ["now","Each piece cleans up on its own",""],
 ["us","This is why teardown is now reliable","Recording, transcript, metrics and events all get written, even on a bad ending."]
]);

les(1,"The goodbye that never got said",[
 ["setup","There is a closing line, and a nudge for a silent caller",""],
 ["before","Both could be silently thrown away","In the worst case the call ended with no goodbye at all."],
 ["now","They get spoken",""],
 ["us","For a form call, the closing line is the receipt","It is where the caller is told they are finished."]
]);

les(1,"Closing lines cut off mid-sentence",[
 ["before","Words already queued were cut off","When one part of the call handed over, or the call wrapped up."],
 ["now","The handover waits for them to be spoken",""],
 ["us","The end of a call is now as reliable as the middle",""]
]);

les(2,"Early signals dropped on a slow browser",[
 ["setup","Some messages are sent the instant a call connects",""],
 ["before","A slow browser silently lost them","One of them is the signal that shows the caller they are muted during the greeting."],
 ["now","They are held and delivered when ready",""],
 ["us","So a caller stops wondering why their microphone looks dead",""]
]);

les(2,"Browser audio at half speed",[
 ["before","Audio could come through slow and garbled","In the case where the microphone's own rate already matched the connection's."],
 ["now","Handled correctly",""],
 ["us","Garbled input means garbled transcription","Which means a wrong answer saved to the form."]
]);

les(2,"A runaway loop on a broken microphone",[
 ["before","It retried about a hundred times a second","Instead of waiting. That pins the processor."],
 ["now","It waits properly between attempts",""],
 ["us","One caller could degrade the server for everyone else on it",""]
]);

les(2,"Exotel got a field name Exotel does not use",[
 ["setup","Each chunk of audio carries an identifier for the call",""],
 ["before","We sent it under a name not in Exotel's protocol","They tolerated it, so nothing visibly broke."],
 ["now","Sent under the name they actually define",""],
 ["us","Worth an Exotel call before deploy","A misread identifier sends audio nowhere and kills a call in seconds, and no test in our suite would catch it."]
]);

les(2,"Hanging up took ten seconds",[
 ["before","Up to ten seconds per provider that would not close",""],
 ["now","Two seconds",""],
 ["us","A separate fix stops waiting on an already dead line","Phone calls that drop on the provider's side now end promptly."]
]);

les(3,"Token counts were inflated",[
 ["setup","A model streams its reply back in small chunks","Some providers repeat the running total with every chunk."],
 ["before","Every chunk counted as its own usage report","So those totals were counted over and over."],
 ["now","Usage is reported once per completed reply",""],
 ["us","Our cost tracking gets this for free","Whether we were over-counting depends on what OpenRouter sends per chunk. Either way the new behaviour is the correct one."]
]);

les(3,"Response time measured the same for everyone",[
 ["before","Some models effectively got a head start","So the number was not comparable between them."],
 ["now","Measured identically for all",""],
 ["us","That number may shift on deploy","That is it becoming correct, not a regression."],
 ["us","One known gap stays","Our figure measures time to the first thinking token, not the first spoken word. For a reasoning model it understates the real wait."]
]);

les(3,"Dates read aloud in mixed languages",[
 ["before","A month name could come out in a different language","If the server's own language setting was not English."],
 ["now","Consistent whatever the server is set to",""],
 ["us","Directly ours","Dates are one of the answer types these forms ask for and read back."]
]);

les(3,"The transcript did not match what was said",[
 ["before","The saved record could differ from the sound","If the voice provider adjusted text on the way out. Logging <b>cafe</b> where the agent said <b>café</b>."],
 ["now","The saved record matches",""],
 ["us","Our transcripts are the product","Customers read them. They are not a debugging aid."]
]);

les(4,"The pause detector got nine times smaller",[
 ["setup","A model judges when a caller has really finished","Used in bulk dictation, loaded on the call server."],
 ["num","566 MB → 60 MB","memory held, with no change in accuracy"],
 ["num","5s → 0.3s","to start up"],
 ["us","It also stopped pulling in one large library","Smaller install, faster restarts, less memory pressure."]
]);

les(4,"Agent startup roughly halved",[
 ["before","Everything loaded up front","Whether a call needed it or not."],
 ["now","Rarely used pieces load when first needed",""],
 ["us","Faster restarts and deploys","No effect on a call already running."]
]);

les(4,"Connections now open in parallel",[
 ["before","Speech, voice and language services connected one by one",""],
 ["now","All at once",""],
 ["us","One cost sits next to it","The noise filter's model cache lives inside the container image, so the model is fetched again on the first call after each deploy."]
]);

les(4,"Every call left a worker behind",[
 ["before","Each call leaked an idle worker thread","Building up over time."],
 ["now","Cleaned up when the call ends","And the voice detection the call set up is now torn down once, not twice."],
 ["us","Our back end is long-running","It takes call after call, so a per-call leak is the kind that eventually pages someone."]
]);

les(5,"Two classes were renamed",[
 ["before","Both classes that run a call were renamed","And starting the runner went from one call to two."],
 ["now","Updated everywhere, including the recording tests","No old name is left in the tree."],
 ["us","The old names still work, for now","They print a warning and disappear in Pipecat 2.0."]
]);

les(5,"The Overall Latency chart was removed",[
 ["before","Four things fed that chart","The chart, a per-turn accumulator, a reset called on every caller turn, and a copy of the series in the JSON view."],
 ["now","All four gone","Nothing anywhere in the repository still mentions them."],
 ["us","The per-service charts and typing indicator survived","They sat inside the deleted blocks and were deliberately kept."]
]);

les(6,"Recordings get longer",[
 ["before","A real gap of silence was squashed out of the file","As if the pause had never happened."],
 ["now","The silence is written into the file","So the recording runs at the real pace of the call. Time spent waiting on a model now takes up space in the audio."],
 ["us","Not comparable across the deploy date","If anyone investigates a step in recording durations, the deploy is the answer."]
]);

les(6,"Call duration steps up about 2 seconds",[
 ["setup","A call's length comes from its first transcript timestamp","And every timestamp is written when an utterance finishes."],
 ["before","The greeting and first question shared one row","That row is timestamped when the question finishes speaking, so the clock started late."],
 ["now","They are separate rows now","The greeting gets its own timestamp, which is earlier by however long the first question takes to say."],
 ["us","Customers can see this number","It is served from the analytics endpoint. The new value is the more accurate one, and the deploy date is the discontinuity."]
]);

les(6,"A broken API key now fails quietly",[
 ["before","It logged an error several times a second","Noisy. But that noise is how you noticed."],
 ["now","The service gives up and reports itself broken","It says so once, instead of failing loudly every second."],
 ["us","Nothing of ours is listening for that report","Until something is, a genuinely broken key just looks like silence."]
]);

les(7,"A faster Sarvam transcription service",[
 ["setup","A new Sarvam service, built for lower delay","Between the caller speaking and the text arriving."],
 ["us","The most interesting item here","That delay sits in front of everything: the pause decision, the form filling, the reply. An improvement is felt on every turn."],
 ["us","Nothing changes unless we switch","Worth a look if transcript delay ever becomes the bottleneck."]
]);

les(7,"The newer Sarvam model, v4",[
 ["setup","<code>saaras:v4</code> adds global English","On top of the Indian English and Indic languages v3 already covers."],
 ["us","Deliberately not taken here","Our prompts, turn-stop timings and extraction rules were all tuned against v3."],
 ["us","It needs its own evaluation","With the Pipecat upgrade already settled underneath it."]
]);

les(7,"Telling transcription which words to expect",[
 ["setup","Several providers now accept a list of expected words","So unusual terms are recognised more reliably."],
 ["us","A direct fit for these forms","Anganwadi, ICDS, district and centre names, facility codes. The words a general model is weakest on and our forms depend on most."],
 ["us","Blocked for now","Available on Google, Cartesia and Smallest. Not on Sarvam, which is what we run."]
]);

les(7,"Phone keypad presses as an answer",[
 ["setup","Key presses can now be treated as an answer","Handled the same way spoken words are, rather than ignored."],
 ["us","Unambiguous where speech is not","Good for a question with fixed options, or a number that speech-to-text keeps mishearing on a noisy line."],
 ["us","The path already exists","We run calls over Twilio and Exotel. This is a product decision, not a technical one."]
]);

les(7,"Seconds of audio measured per call",[
 ["setup","Every transcription provider now reports what it processed","In seconds of audio."],
 ["us","Nothing to switch on","We already have usage numbers enabled, so this arrives with the upgrade."],
 ["us","Useful next to cost tracking","Today we estimate speech-to-text cost from the audio after the call. This would be a measured figure instead."]
]);

les(7,"Numbers and dates spoken more naturally",[
 ["setup","Numbers, money, dates and acronyms can be expanded before speaking","While the written transcript keeps the original text."],
 ["us","These forms read numbers back for confirmation","How a centre code or a number of months is spoken decides whether the caller can confirm it."],
 ["us","Available for Google, our production voice","Off unless we turn it on."]
]);

les(7,"Thinking time measured apart from answering",[
 ["setup","A new measurement splits the two","Silent thinking, then the first word of the actual answer."],
 ["us","Sharper than what we have","Our figure measures time to the first thinking token, so for a reasoning model it understates the caller's real wait."],
 ["us","Left out on purpose","Adopting it touches the latency observer, the metrics file and the analytics reading that file. More than a version bump should carry."]
]);
